<html lang="zh-CN">
<head>
<meta charset="utf-8"/>
<style>
  html,body{margin:0;padding:0;overflow:hidden;background:#F5F2E9;}
  *{box-sizing:border-box;}
  :root{
    --bg:#F5F2E9;
    --surface:#F3F0E7;
    --ink:#1B2620;
    --muted:#5C665D;
    --olive:#4F5E43;
    --gold:#B4914A;
    --blue:#8C9FB2;
    --line:#A3AC9E;
    --serif:"Bodoni Moda",Georgia,"Times New Roman","Songti SC","Noto Serif CJK SC",serif;
    --sans:"Archivo","Helvetica Neue",Arial,"PingFang SC","Microsoft YaHei",sans-serif;
  }
  .slide{
    position:relative;width:1920px;height:1080px;overflow:hidden;
    background:#F5F2E9;color:var(--ink);font-family:var(--sans);
  }
  /* ---------- background field ---------- */
  .bg{
    position:absolute;inset:0;z-index:0;
    background:
      radial-gradient(1100px 780px at 2% 0%,rgba(180,145,74,.10),transparent 70%),
      radial-gradient(900px 760px at 50% 50%,rgba(140,159,178,.10),transparent 70%),
      radial-gradient(950px 760px at 96% 96%,rgba(79,94,67,.11),transparent 72%),
      linear-gradient(168deg,#F8F5EC 0%,#F5F2E9 52%,#EFECE1 100%);
  }
  .bg:after{
    content:"";position:absolute;inset:0;
    background:repeating-linear-gradient(90deg,rgba(27,38,32,.04) 0 1px,transparent 1px 160px);
  }
  .dots{
    position:absolute;z-index:1;right:150px;top:0;width:470px;height:150px;opacity:.32;
    background-image:radial-gradient(circle,rgba(27,38,32,.45) 1.05px,transparent 1.15px);
    background-size:15px 15px;
  }
  .prism{
    position:absolute;z-index:1;left:700px;top:-300px;width:150px;height:1500px;
    transform:rotate(17deg);
    background:linear-gradient(180deg,rgba(140,159,178,.18),rgba(140,159,178,.06) 72%,rgba(140,159,178,0));
  }
  .prism:after{content:"";position:absolute;left:84px;top:0;width:64px;height:1500px;background:rgba(255,255,255,.36);}

  /* ---------- register ornament ---------- */
  .register{position:absolute;right:-88px;top:-118px;width:330px;height:330px;z-index:3;}
  .register .r1{position:absolute;inset:0;border-radius:50%;border:1px solid rgba(27,38,32,.30);}
  .register .r2{position:absolute;inset:16px;border-radius:50%;border:1px solid rgba(27,38,32,.16);}
  .register .r3{
    position:absolute;inset:36px;border-radius:50%;
    background:conic-gradient(from 210deg,rgba(79,94,67,.20),rgba(79,94,67,0) 24%,rgba(140,159,178,.30) 52%,rgba(140,159,178,.06) 78%,rgba(79,94,67,.20));
  }
  .register .r4{position:absolute;inset:56px;border-radius:50%;background:rgba(245,242,233,.92);border:1px solid rgba(27,38,32,.08);}
  .register .r5{position:absolute;inset:78px;border-radius:50%;background:rgba(140,159,178,.22);border:1px solid rgba(27,38,32,.08);}

  /* ---------- frame ---------- */
  .top-rule{position:absolute;left:96px;top:48px;width:1728px;height:1px;background:rgba(27,38,32,.34);z-index:6;}
  .left-rule{position:absolute;left:60px;top:40px;width:1px;height:1000px;background:rgba(27,38,32,.26);z-index:6;}
  .meta{
    position:absolute;left:98px;top:61px;z-index:15;
    font-size:15px;font-weight:600;letter-spacing:4.2px;color:#4f5b53;
  }
  .rail-label{
    position:absolute;left:44px;top:560px;z-index:15;transform:rotate(-90deg);transform-origin:left top;
