  }
  .rail-tick{position:absolute;left:54px;width:13px;height:1px;background:rgba(27,38,32,.42);z-index:7;}
  .rail-tick.t1{top:300px;}
  .rail-tick.t2{top:840px;}

  /* ---------- header ---------- */
  header{position:absolute;left:96px;top:150px;width:1200px;z-index:10;}
  .eyebrow{
    display:flex;align-items:center;gap:16px;
    font-size:15px;font-weight:700;letter-spacing:6px;color:var(--gold);
  }
  .eyebrow i{display:block;width:56px;height:1px;background:var(--gold);opacity:.85;}
  h1{
    margin:26px 0 0 0;font-family:var(--serif);font-size:106px;font-weight:700;
