  .lede{
    margin:26px 0 0 0;max-width:1020px;
    font-size:23px;line-height:1.7;letter-spacing:1.2px;color:var(--muted);
  }

  /* ---------- cards ---------- */
  .cards{
    position:absolute;left:96px;top:452px;width:1728px;
    display:flex;gap:32px;z-index:10;
  }
  .card{
    position:relative;width:554px;height:344px;padding:38px 38px 32px 38px;
