  .card:nth-child(2){border-top-color:var(--gold);}
  .card:nth-child(3){border-top-color:#7E93A8;}

  /* corner accent: pinned to the card's top-right corner, far from the index numeral */
  .card .corner{
    position:absolute;right:30px;top:30px;width:34px;height:34px;
    border-top:1.5px solid rgba(79,94,67,.55);
    border-right:1.5px solid rgba(79,94,67,.55);
    pointer-events:none;
  }
  .card:nth-child(2) .corner{border-top-color:rgba(180,145,74,.65);border-right-color:rgba(180,145,74,.65);}
  .card:nth-child(3) .corner{border-top-color:rgba(126,147,168,.75);border-right-color:rgba(126,147,168,.75);}

  .card .num{
    display:block;height:44px;
    font-family:var(--serif);font-size:44px;font-weight:700;line-height:44px;
    letter-spacing:2px;color:rgba(27,38,32,.32);
  }
  .card h2{
    margin:22px 0 0 0;font-size:38px;font-weight:700;letter-spacing:3px;color:#1B2620;
  }
  .card p{
    margin:18px 0 0 0;font-size:21px;line-height:1.75;letter-spacing:.8px;color:var(--muted);
  }
  .card .foot{
    position:absolute;left:38px;right:38px;bottom:28px;
    padding-top:16px;border-top:1px solid rgba(27,38,32,.16);
    font-size:14px;font-weight:600;letter-spacing:3.2px;color:#7b857a;
    background:transparent;
  }

  /* ---------- boundary strip ---------- */
  .boundary{
    position:absolute;left:96px;top:864px;width:1728px;z-index:10;
    display:flex;align-items:center;gap:28px;
    padding-top:26px;border-top:1px solid rgba(27,38,32,.28);
  }
  .boundary .tag{
    flex:0 0 auto;padding:8px 16px;border:1px solid rgba(180,145,74,.9);
    font-size:14px;font-weight:700;letter-spacing:3px;color:#8E7033;
  }
  .boundary .txt{
    font-size:22px;line-height:1.6;letter-spacing:1px;color:#3A453C;
  }
  .boundary .note{
    margin-left:auto;font-size:15px;font-weight:600;letter-spacing:3px;color:#8b948a;
  }

  /* ---------- page number ---------- */
  .page-no{
    position:absolute;right:96px;bottom:44px;z-index:15;
    font-size:16px;font-weight:700;letter-spacing:3.4px;color:#657066;
  }
  .page-no:before{
    content:"";display:inline-block;width:44px;height:1px;background:rgba(27,38,32,.4);
    vertical-align:middle;margin-right:14px;
  }
</style>
</head>
<body>
<main class="slide">
  <div class="bg"></div>
  <div class="dots"></div>
  <div class="prism"></div>

  <div class="register">
    <div class="r1"></div><div class="r2"></div><div class="r3"></div><div class="r4"></div><div class="r5"></div>
  </div>

  <div class="top-rule"></div>
  <div class="left-rule"></div>
  <div class="rail-tick t1"></div>
  <div class="rail-tick t2"></div>
  <div class="meta">澄图工单云 · 产品介绍</div>
  <div class="rail-label">PRODUCT CAPABILITY</div>

  <header>
    <div class="eyebrow"><i></i>03 · 功能范围</div>
    <h1>产品能力</h1>
    <p class="lede">以下三项为资料中明确记载的功能范围，对应工单协作的三个环节。</p>
  </header>

  <section class="cards">
    <article class="card">
      <div class="corner"></div>
      <span class="num">01</span>
      <h2>工单归类</h2>
      <p>将工单按类别归集。</p>
      <div class="foot">协作环节 · 归类</div>
    </article>

    <article class="card">
      <div class="corner"></div>
      <span class="num">02</span>
      <h2>责任人分派</h2>
      <p>为工单指定责任人。</p>
      <div class="foot">协作环节 · 分派</div>
    </article>

    <article class="card">
      <div class="corner"></div>
      <span class="num">03</span>
      <h2>状态追踪</h2>
      <p>跟踪工单处理状态。</p>
      <div class="foot">协作环节 · 追踪</div>
    </article>
  </section>

  <div class="boundary">
    <span class="tag">资料边界</span>
    <span class="txt">资料未包含集成能力、权限模型、价格或性能指标。</span>
    <span class="note">待补充</span>
  </div>

  <div class="page-no">3 / 6</div>
</main>
</body>
</html>"}, {"page_id": "b", "page_revision": "ab4e9d4995b87fad8b29ae84e1fd1f9daf2d83fd2bb30f4ee467cfc1f3bde4ef", "html": "<!doctype html>
